import Foundation
import SwiftUI

// Equivalente ao teu 'object Logos' do Kotlin
enum Logos {
    // Cola a tua string Base64 gigante dentro das aspas abaixo
    static let almaNaBocaLogoB64 = ""
}

// Extensão útil para converter a String Base64 diretamente numa Image do SwiftUI
extension String {
    func toImage() -> Image? {
        // 1. Tenta converter a string em Data
        guard let data = Data(base64Encoded: self, options: .ignoreUnknownCharacters) else {
            return nil
        }
        // 2. Tenta criar uma UIImage a partir dos dados
        guard let uiImage = UIImage(data: data) else {
            return nil
        }
        // 3. Retorna a Image do SwiftUI
        return Image(uiImage: uiImage)
    }
}
